//! Native derivative goldens: cea==3.3.4 (PyPI), macOS arm64, default hard
//! truncation, complete products_from_reactants=True pools and no ions.
//! For each mixture solve TP at 2500 K, 10 bar; take its H/S for HP/SP.
//! Solve each mode, construct cea.EqDerivatives(solver, solution), and call
//! compute_derivatives(check_closure_defect=True). Convert output H/U/G/S
//! from kJ to J, the pressure column from per-bar to per-Pa, and HP/SP's
//! first column from per-(input/R) to per-SI-input by dividing by cea.R.
//! Rows/columns below follow [state1,state2,raw reactant weights...].
use cea_rs::{
    derivatives::EqDerivatives,
    solver::{Mode, Solver},
    thermo::Reactant,
};
fn solver(names: &[&str]) -> Solver {
    Solver::new(
        names.iter().map(|n| Reactant::named(n).unwrap()).collect(),
        true,
        false,
        None,
        vec![],
    )
    .unwrap()
}
fn close(actual: &[f64], expected: &[f64], absolute: f64) {
    assert_eq!(actual.len(), expected.len());
    for (i, (&a, &b)) in actual.iter().zip(expected).enumerate() {
        assert!(
            (a - b).abs() <= 1e-4 * b.abs() + absolute,
            "column {i}: {a:e} != {b:e}"
        );
    }
}
