fn rows(d: &EqDerivatives) -> Vec<&Vec<f64>> {
    [
        &d.temperature,
        &d.total_moles,
        &d.enthalpy,
        &d.energy,
        &d.gibbs_energy,
        &d.entropy,
    ]
    .into_iter()
    .chain(d.species_amounts.values())
    .collect()
}
#[test]
fn analytic_matches_public_finite_differences_in_all_modes() {
    for (names, w) in [
        (vec!["H2", "O2"], vec![1.0, 8.0]),
        (vec!["CH4", "O2", "N2"], vec![1.0, 4.0, 13.0]),
        (vec!["CO"], vec![1.0]),
    ] {
        let mut s = solver(&names);
        if names == ["CO"] {
            s = Solver::new(
                vec![Reactant::named("CO").unwrap()],
                true,
                false,
                None,
                vec!["C(gr)".into()],
            )
            .unwrap();
        }
        let t = if names == ["CO"] { 800.0 } else { 2500.0 };
        let tp = s.solve(Mode::TP(t, 1e6), &w).unwrap();
        let v = 1.0 / tp.density_kg_m3;
        for mode in [
            Mode::TP(t, 1e6),
            Mode::HP(tp.enthalpy_j_kg, 1e6),
            Mode::SP(tp.entropy_j_kg_k, 1e6),
            Mode::TV(t, v),
            Mode::UV(tp.energy_j_kg, v),
            Mode::SV(tp.entropy_j_kg_k, v),
        ] {
            if names == ["CO"] && matches!(mode, Mode::UV(..) | Mode::SV(..)) {
                assert!(s.derivatives(mode, &w).is_err());
                continue;
            }
            let analytic = s
                .derivatives(mode, &w)
                .unwrap_or_else(|e| panic!("{names:?} {mode:?}: {e}"));
            let fd = s.finite_difference_derivatives(mode, &w, 1e-5).unwrap();
            assert!(fd.closure_defect.is_none());
            for (row, (a, f)) in rows(&analytic)
                .into_iter()
                .zip(rows(&fd))
                .take(6)
                .enumerate()
            {
                for (col, (&a, &f)) in a.iter().zip(f).enumerate() {
                    // Independent solves stop at a finite constraint residual;
                    // their noise dominates FD of an exactly zero H/U/S row.
                    let tolerance = if a == 0.0 && row >= 2 {
                        1.0
                    } else {
                        1e-4 * a.abs() + 1e-7
                    };
                    assert!(
                        (a - f).abs() <= tolerance,
                        "{names:?} {mode:?} row {row} column {col}: {a:e} vs FD {f:e}"
                    );
                }
            }
            for (name, a) in &analytic.species_amounts {
                close(&fd.species_amounts[name], a, 1e-19);
            }
            // Scaling all masses cannot change a per-kg equilibrium state.
            for row in rows(&analytic) {
                let homogeneous: f64 = row[2..].iter().zip(&w).map(|(d, w)| d * w).sum();
                let scale: f64 = row[2..].iter().zip(&w).map(|(d, w)| (d * w).abs()).sum();
                assert!(homogeneous.abs() < 1e-10 * scale.max(1e-20));
            }
        }
    }
}
#[test]
fn derivative_failures_are_errors_and_zero_weights_are_one_sided() {
    let s = solver(&["H2", "O2"]);
    for h in [0.0, -1.0, 0.1, f64::NAN, f64::INFINITY] {
        assert!(
            s.finite_difference_derivatives(Mode::TP(2500.0, 1e6), &[1.0, 8.0], h)
                .is_err()
        );
    }
    assert!(s.derivatives(Mode::TP(2500.0, 1e6), &[0.0, 0.0]).is_err());
    assert!(
        s.finite_difference_derivatives(Mode::TP(160.0, 1e6), &[1.0, 8.0], 1e-4)
            .is_err()
    );
    // Both reactants carry the same element, so the zero-weight perturbation
    // keeps the product pool and has an analytic comparison at the boundary.
    let s = solver(&["H2", "H"]);
    let a = s.derivatives(Mode::TP(2500.0, 1e6), &[1.0, 0.0]).unwrap();
    let f = s
        .finite_difference_derivatives(Mode::TP(2500.0, 1e6), &[1.0, 0.0], 1e-4)
        .unwrap();
    for (a, f) in rows(&a).into_iter().zip(rows(&f)) {
        close(f, a, 1e-4);
    }
    // Introducing oxygen at a zero weight changes the compatible product pool.
    let s = solver(&["H2", "O2"]);
    assert!(s.derivatives(Mode::TP(2500.0, 1e6), &[1.0, 0.0]).is_err());
    assert!(
        s.finite_difference_derivatives(Mode::TP(2500.0, 1e6), &[1.0, 0.0], 1e-4)
            .is_err()
    );
    let s = Solver::new(
        vec![Reactant::named("H2").unwrap()],
        false,
        true,
        Some(vec!["H".into(), "H2".into(), "H+".into(), "e-".into()]),
        vec![],
    )
    .unwrap();
    assert!(s.derivatives(Mode::TP(10000.0, 1e5), &[1.0]).is_err());
    let d = s
        .finite_difference_derivatives(Mode::TP(10000.0, 1e5), &[1.0], 1e-4)
        .unwrap();
    for c in 0..3 {
        assert!((d.species_amounts["H+"][c] - d.species_amounts["e-"][c]).abs() < 1e-10);
    }
}
